describe('Bulk Delete Items from List', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="items-list"]').should('be.visible');
  });

  it('should bulk delete multiple selected items from the list', () => {
    // Verify initial items are present
    cy.get('[data-testid="list-item"]').should('have.length.greaterThan', 2);

    // Select first item
    cy.get('[data-testid="list-item"]').first().within(() => {
      cy.get('[data-testid="item-checkbox"]').check();
    });

    // Select second item
    cy.get('[data-testid="list-item"]').eq(1).within(() => {
      cy.get('[data-testid="item-checkbox"]').check();
    });

    // Verify checkboxes are checked
    cy.get('[data-testid="item-checkbox"]:checked').should('have.length', 2);

    // Click bulk delete button
    cy.get('[data-testid="bulk-delete-btn"]').should('be.visible').click();

    // Confirm deletion in modal
    cy.get('[data-testid="confirm-delete-modal"]').should('be.visible');
    cy.get('[data-testid="confirm-delete-btn"]').click();

    // Verify items are deleted
    cy.get('[data-testid="list-item"]').should('have.length.lessThan', 3);
    cy.get('[data-testid="success-message"]').should('contain', 'Items deleted successfully');
  });

  it('should not delete items when canceling bulk delete operation', () => {
    // Get initial count
    cy.get('[data-testid="list-item"]').then(($items) => {
      const initialCount = $items.length;

      // Select items
      cy.get('[data-testid="list-item"]').first().within(() => {
        cy.get('[data-testid="item-checkbox"]').check();
      });

      cy.get('[data-testid="list-item"]').eq(1).within(() => {
        cy.get('[data-testid="item-checkbox"]').check();
      });

      // Click bulk delete button
      cy.get('[data-testid="bulk-delete-btn"]').click();

      // Cancel deletion
      cy.get('[data-testid="confirm-delete-modal"]').should('be.visible');
      cy.get('[data-testid="cancel-delete-btn"]').click();

      // Verify modal is closed
      cy.get('[data-testid="confirm-delete-modal"]').should('not.exist');

      // Verify items count remains the same
      cy.get('[data-testid="list-item"]').should('have.length', initialCount);

      // Verify checkboxes are still checked
      cy.get('[data-testid="item-checkbox"]:checked').should('have.length', 2);
    });
  });

  it('should disable bulk delete button when no items are selected', () => {
    // Verify bulk delete button is disabled when nothing is selected
    cy.get('[data-testid="bulk-delete-btn"]').should('be.disabled');

    // Select one item
    cy.get('[data-testid="list-item"]').first().within(() => {
      cy.get('[data-testid="item-checkbox"]').check();
    });

    // Verify button is enabled
    cy.get('[data-testid="bulk-delete-btn"]').should('not.be.disabled');

    // Deselect the item
    cy.get('[data-testid="list-item"]').first().within(() => {
      cy.get('[data-testid="item-checkbox"]').uncheck();
    });

    // Verify button is disabled again
    cy.get('[data-testid="bulk-delete-btn"]').should('be.disabled');
  });
});
